<script setup lang="ts">
import { Form,Head,Link,router } from '@inertiajs/vue3';import{computed,ref}from'vue';import{Dumbbell,Pencil,Plus,Search,Trash2,X}from'@lucide/vue';import{Button}from'@/components/ui/button';import{Input}from'@/components/ui/input';import{Label}from'@/components/ui/label';
type Item={id:number;name:string;specialty:string|null;phone:string|null};type L={url:string|null;label:string;active:boolean};type P={trainers:{data:Item[];current_page:number;last_page:number;total:number;links:L[]};filters:{search:string};stats:{total:number}};const props=defineProps<P>();const show=ref(false),editing=ref<Item|null>(null),key=ref(0),search=ref(props.filters.search??'');const title=computed(()=>editing.value?'Edit trainer':'Add new trainer'),action=computed(()=>editing.value?`/trainers/${editing.value.id}`:'/trainers'),method=computed(()=>editing.value?'put':'post');function create(){editing.value=null;key.value++;show.value=true}function edit(x:Item){editing.value=x;key.value++;show.value=true}function close(){show.value=false;editing.value=null}function filter(){router.get('/trainers',{search:search.value||undefined},{preserveState:true,replace:true})}function reset(){search.value='';filter()}function remove(x:Item){if(confirm(`Hapus ${x.name}?`))router.delete(`/trainers/${x.id}`)}
</script><template><Head title="Trainers"/><div class="space-y-6 p-4 md:p-6"><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-medium text-primary">Master Data</p><h1 class="mt-1 text-2xl font-semibold tracking-tight">Trainers</h1><p class="mt-1 text-sm text-muted-foreground">Kelola data trainer dan spesialisasinya.</p></div><Button @click="create"><Plus class="mr-2 size-4"/> Add trainer</Button></div><div class="rounded-2xl border bg-card p-4 shadow-sm"><div class="flex justify-between"><span class="text-sm text-muted-foreground">Total trainers</span><Dumbbell class="size-4 text-muted-foreground"/></div><div class="mt-3 text-2xl font-semibold">{{props.stats.total}}</div></div><div class="rounded-2xl border bg-card shadow-sm"><div class="flex gap-3 border-b p-4"><div class="relative flex-1"><Search class="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input v-model="search" @keyup.enter="filter" class="pl-9" placeholder="Search trainer..."/></div><Button variant="secondary" @click="filter">Filter</Button><Button variant="ghost" @click="reset">Reset</Button></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-muted/40 text-left text-xs uppercase tracking-wide text-muted-foreground"><tr><th class="px-5 py-3">Name</th><th class="px-5 py-3">Specialty</th><th class="px-5 py-3">Phone</th><th class="px-5 py-3 text-right">Action</th></tr></thead><tbody class="divide-y"><tr v-for="x in props.trainers.data" :key="x.id" class="hover:bg-muted/20"><td class="px-5 py-4 font-medium"><Link :href="`/trainers/${x.id}`" class="text-primary hover:underline">{{x.name}}</Link></td><td class="px-5 py-4">{{x.specialty||'—'}}</td><td class="px-5 py-4 text-muted-foreground">{{x.phone||'—'}}</td><td class="px-5 py-4"><div class="flex justify-end gap-1"><Button variant="ghost" size="icon" @click="edit(x)"><Pencil class="size-4"/></Button><Button variant="ghost" size="icon" @click="remove(x)"><Trash2 class="size-4 text-destructive"/></Button></div></td></tr><tr v-if="!props.trainers.data.length"><td colspan="4" class="px-5 py-16 text-center">No trainers found</td></tr></tbody></table></div></div></div><div v-if="show" class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"><div class="w-full max-w-lg rounded-2xl border bg-background shadow-2xl"><div class="flex justify-between border-b p-5"><div><p class="text-sm font-medium text-primary">Trainer management</p><h2 class="text-xl font-semibold">{{title}}</h2></div><Button variant="ghost" size="icon" @click="close"><X class="size-4"/></Button></div><Form :key="key" :action="action" :method="method" class="space-y-4 p-5" @success="close" v-slot="{processing}"><div><Label>Name</Label><Input name="name" :default-value="editing?.name" required/></div><div><Label>Specialty</Label><Input name="specialty" :default-value="editing?.specialty??''" placeholder="e.g. Personal Trainer"/></div><div><Label>Phone</Label><Input name="phone" :default-value="editing?.phone??''" placeholder="08..."/></div><div class="flex justify-end gap-2 border-t pt-4"><Button type="button" variant="ghost" @click="close">Cancel</Button><Button type="submit" :disabled="processing">{{editing?'Save changes':'Create trainer'}}</Button></div></Form></div></div></template>